import React from 'react';
import { RotateCcw } from 'lucide-react';
import { TrackerRow } from '../../models';
import { METRICS, PRIORITY_DATA, TRACKER_DATA, URGENT_TASKS } from '../MockData/data';
import { motion } from 'framer-motion';
import MetricCard from './matric';
import TrackerTable from './TrackerTable';
import PriorityWidget from './PriorityWidget';
import UrgentWidget from './UrgentWidget';

interface DashboardProps {
  activeMetric: string;
  onMetricChange: (id: string) => void;
  onRowClick: (row: TrackerRow) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ activeMetric, onMetricChange, onRowClick }) => {
  const selectedMetric = METRICS.find(m => m.id === activeMetric) || METRICS[0];

  return (
    <motion.div
      key="dashboard"
      initial={{ opacity: 0, x: -20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: 20 }}
      transition={{ duration: 0.3 }}
    >
      {/* Filters */}
      <div className="flex items-center justify-between mb-8 bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
        <div className="flex items-center gap-6">
          <div className="flex items-center gap-3">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Dept.</span>
            <select className="bg-slate-50 border border-slate-200 rounded-lg px-3 py-1.5 text-sm font-medium focus:outline-none">
              <option>All Departments</option>
              <option>Mining</option>
              <option>Engineering</option>
            </select>
          </div>
          <div className="w-px h-6 bg-slate-200" />
          <div className="flex items-center gap-3">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Nationality</span>
            <select className="bg-slate-50 border border-slate-200 rounded-lg px-3 py-1.5 text-sm font-medium focus:outline-none">
              <option>All Nationalities</option>
              <option>Local</option>
              <option>Expat</option>
            </select>
          </div>
        </div>
        <button className="flex items-center gap-2 text-blue-600 hover:text-blue-700 font-bold text-xs uppercase tracking-wider transition-colors">
          <RotateCcw size={14} /> Reset
        </button>
      </div>

      {/* Metrics Grid */}
      <div className="flex grid-cols-4 lg:grid-cols-8 gap-4 mb-8">
        {METRICS.map((metric) => (
          <MetricCard
            key={metric.id}
            metric={metric}
            active={activeMetric === metric.id}
            onClick={() => onMetricChange(metric.id)}
          />
        ))}
      </div>

      <div className="flex gap-8">
        <div className="flex-[2] flex flex-col gap-6">
          <TrackerTable
            data={TRACKER_DATA}
            activeMetric={activeMetric}
            selectedMetric={selectedMetric}
            onRowClick={onRowClick}
          />
        </div>
        <div className="flex-1 flex flex-col gap-6">
          <PriorityWidget data={PRIORITY_DATA} />
          <UrgentWidget tasks={URGENT_TASKS} />
        </div>
      </div>
    </motion.div>
  );
};

export default Dashboard;
